/// <summary>
/// Extension of table <c>CustConfirmTrans</c>.
/// </summary>
[ExtensionOf(tableStr(CustConfirmTrans))]
final class METCustConfirmTransTbl_Extension
{
}

Method.Source:
    /// <summary>
    /// Initializes <c>CustConfirmTrans</c> from <c>SalesLine</c>.
    /// </summary>
    /// <param name = "_salesLine"><c>SalesLine</c>.</param>
    void  initFromSalesLine(SalesLine _salesLine)
    {
        next initFromSalesLine(_salesLine);

        this.METSetReasonId(_salesLine);
    }

    /// <summary>
    /// CB232_AutoSettingItemStockStatus.
    /// Sets reason Id field.
    /// </summary>
    /// <param name = "_salesLine"><c>SalesLine</c>.</param>
    private void metSetReasonId(SalesLine _salesLine)
    {
        METInventItemOrderSetup     itemOrderSetup;
        EcoResProductLifecycleState productLifeCycleState;
        InventDim                   inventDim;
        METSalesLine                metSalesLine;
        InventQty                   qtyOrdered,
                                    qtySupplied, 
                                    qtyLeft;
       
        metSalesLine = _salesLine.metSalesLine();
        
        if (metSalesLine.ReasonId)
        {
            this.METReasonId = metSalesLine.ReasonId;
            return;
        }

        qtyOrdered  = _salesLine.QtyOrdered;
        qtySupplied = this.metGetTotalSuppliedQty(_salesLine.InventTransId);
        qtyLeft     = qtyOrdered - qtySupplied;

        if (qtyLeft == 0)
        {
            return;
        }
        else if (qtyLeft > 0)
        {
            inventDim = _salesLine.inventDim();
            itemOrderSetup = METInventItemOrderSetup::findByItemAndSite(_salesLine.ItemId, inventDim.InventSiteId);

            if (!itemOrderSetup)
            {
                return;
            }

            productLifeCycleState = itemOrderSetup.ecoResProductLifecycleState();
  
            if (productLifeCycleState.METStatus == METEcoResProductLifecycleStateStatus::Recall)
            {
                this.METReasonId = enum2Str(METEcoResProductLifecycleStateStatus::Recall);
                return;
            }

            if (itemOrderSetup.ItemStatus == METConstants::ItemStatusPackChange)
            {
                this.METReasonId = itemOrderSetup.ItemStatus;
                return;
            }

            if (productLifeCycleState.METStatus == METEcoResProductLifecycleStateStatus::LTNA)
            {
                this.METReasonId = enum2Str(METEcoResProductLifecycleStateStatus::LTNA);
            }
            else
            {
                if (itemOrderSetup.StockAvailDate != dateNull())
                {
                    TransDate today = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
                        
                    if (itemOrderSetup.StockAvailDate < today)
                    {
                        this.METReasonId = METConstants::TNA;
                    }
                    else if (itemOrderSetup.StockAvailDate > today)
                    {
                        this.METReasonId = METConstants::TOS;
                    }
                }
            }
        }
    }

    /// <summary>
    /// CB232_AutoSettingItemStockStatus.
    /// Gets total supplied/picked qty per salesline.
    /// </summary>
    /// <param name = "_inventTrans"><c>InventTrans</c>.</param>
    /// <returns>Total supplied/picked qty.</returns>
    private InventQty metGetTotalSuppliedQty(InventTransId _inventTrans)
    {
        InventTransOrigin inventTransOrigin;
        InventTrans       inventTrans;

        select sum(Qty) from inventTrans
            where inventTrans.StatusIssue == StatusIssue::Picked
            exists join inventTransOrigin
                where inventTransOrigin.RecId == inventTrans.InventTransOrigin
                &&    inventTransOrigin.InventTransId == _inventTrans;

        return abs(inventTrans.Qty);
    }
